<?php require_once 'db.php'; $page_title='Feedback'; csrf_check(); $err=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $name=trim($_POST['name']??'');$message=trim($_POST['message']??'');$rating=max(1,min(5,(int)($_POST['rating']??5)));if($name===''||$message===''){$err='Please enter your name and feedback.';}else{$s=db()->prepare("INSERT INTO feedback(user_id,name,message,rating) VALUES(?,?,?,?)");$s->execute([$_SESSION['user_id']??null,$name,$message,$rating]);flash('Thank you for your feedback.');go('feedback.php');}} $items=db()->query("SELECT name,message,rating,created_at FROM feedback ORDER BY id DESC LIMIT 8")->fetchAll();include 'header.php'; ?>
<section class="section" style="max-width:800px;margin:auto"><div class="eyebrow">WE LISTEN</div><h1 style="font-size:3rem">Tell us how we did.</h1><?php if($err): ?><div class="notice"><?= h($err) ?></div><?php endif; ?><form class="panel" method="post"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><div class="field"><label>Your name</label><input name="name" value="<?= h($_SESSION['user_name']??'') ?>" required></div><div class="field"><label>Rating</label><select name="rating"><option value="5">5 — Excellent</option><option value="4">4 — Great</option><option value="3">3 — Good</option><option value="2">2 — Fair</option><option value="1">1 — Needs work</option></select></div><div class="field"><label>Feedback</label><textarea name="message" required></textarea></div><button class="btn">Submit feedback</button></form><div class="section-head" style="margin-top:35px"><h2>Recent notes</h2></div><?php foreach($items as $it): ?><div class="panel" style="margin:12px 0"><strong><?= h($it['name']) ?></strong> · <?= str_repeat('★',(int)$it['rating']) ?><p><?= h($it['message']) ?></p><small class="muted"><?= h($it['created_at']) ?></small></div><?php endforeach; ?></section><?php include 'footer.php'; ?>